import{_ as B,I as i,c as o,o as E,a3 as a,b as t,w as l,a as C,J as s,a4 as A}from"./chunks/framework.BusRvirq.js";const m=JSON.parse('{"title":"서버 무인 배치 스케줄러 및 분산 락 기반 디바이스 팜 운영","description":"사내 실기기 랙과 Docker 가상 단말을 대상으로 충돌 없이 야간 무인 회귀 테스트를 수행하는 Redis 분산 락 및 스케줄러 아키텍처","frontmatter":{"title":"서버 무인 배치 스케줄러 및 분산 락 기반 디바이스 팜 운영","shortTitle":"디바이스 팜 스케줄러","category":"모바일 테스트 엔지니어링","sort":23,"description":"사내 실기기 랙과 Docker 가상 단말을 대상으로 충돌 없이 야간 무인 회귀 테스트를 수행하는 Redis 분산 락 및 스케줄러 아키텍처","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/device-farm-scheduler.html"}]]},"headers":[],"relativePath":"synceta/device-farm-scheduler.md","filePath":"ko/synceta/device-farm-scheduler.md","lastUpdated":1791239682000}'),n={name:"synceta/device-farm-scheduler.md"};function d(c,e,D,u,h,_){const r=i("Mermaid");return E(),o("div",null,[e[1]||(e[1]=a('<h1 id="서버-무인-배치-스케줄러-및-분산-락-기반-디바이스-팜-운영" tabindex="-1">서버 무인 배치 스케줄러 및 분산 락 기반 디바이스 팜 운영 <a class="header-anchor" href="#서버-무인-배치-스케줄러-및-분산-락-기반-디바이스-팜-운영" aria-label="Permalink to “서버 무인 배치 스케줄러 및 분산 락 기반 디바이스 팜 운영”">​</a></h1><h2 id="_1-개요-및-대규모-테스트-과제" tabindex="-1">1. 개요 및 대규모 테스트 과제 <a class="header-anchor" href="#_1-개요-및-대규모-테스트-과제" aria-label="Permalink to “1. 개요 및 대규모 테스트 과제”">​</a></h2><p>개발자가 로컬 PC에서 1:1로 테스트하는 환경을 넘어, 사내에 구축된 수십 대의 모바일 실기기(Android 랙, Mac mini 기반 iOS 랙, Docker redroid 가상 디바이스 풀)를 대상으로 <strong>야간 무인 회귀 테스트</strong>를 수행할 때 다음과 같은 동시성 문제가 발생합니다:</p><ol><li><strong>기기 점유 충돌 (Device Contention)</strong>: 서로 다른 프로젝트나 빌드 파이프라인이 동일한 물리 단말기에 동시에 접근하여 테스트가 상호 간섭되거나 비정상 종료되는 현상.</li><li><strong>비정상 종료 시 기기 잠김 (Deadlock)</strong>: 테스트 실행 도중 러너 프로세스가 강제 종료되면 단말기 세션이 점유된 채 방치되어 후속 테스트가 영구 대기하는 현상.</li><li><strong>노치 및 상태 표시줄로 인한 시각적 오탐</strong>: 배터리 잔량 표시, 시계 분/초 변경, 전면 카메라 노치 영역으로 인해 이미지 픽셀 비교 시 실제 앱 결함이 아님에도 실패로 오인하는 문제.</li></ol><p><code>SyncETA</code>는 <strong>NestJS Scheduler &amp; BullMQ 큐</strong>, <strong>Redis 분산 락</strong>, 그리고 <strong>지능형 영역 마스킹 엔진</strong>을 통해 대규모 디바이스 팜의 무인 자동화를 구현하였습니다.</p>',5)),(E(),t(A,null,{default:l(()=>[s(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Cron%5B%22%EC%A0%95%EA%B8%B0%20%EB%B0%B0%EC%B9%98%20%EC%8A%A4%EC%BC%80%EC%A4%84%EB%9F%AC%20(Cron)%22%5D%20--%3E%20Queue%5B%22BullMQ%20%EC%9E%91%EC%97%85%20%EB%8C%80%EA%B8%B0%EC%97%B4%20(Redis)%22%5D%0A%20%20%20%20CI%5B%22CI%2FCD%20%EC%9B%B9%ED%9B%85%20%ED%8A%B8%EB%A6%AC%EA%B1%B0%22%5D%20--%3E%20Queue%0A%20%20%20%20%0A%20%20%20%20Queue%20--%3E%20Worker%5B%22%EC%8A%A4%EC%BC%80%EC%A4%84%EB%9F%AC%20%EC%9E%91%EC%97%85%20%EB%94%94%EC%8A%A4%ED%8C%A8%EC%B2%98%20(WorkerHost)%22%5D%0A%20%20%20%20Worker%20--%3E%20Lock%7B%22Redis%20%EB%B6%84%EC%82%B0%20%EB%9D%BD%20%ED%9A%8D%EB%93%9D%20(device%3Alock%3Aid)%22%7D%0A%20%20%20%20%0A%20%20%20%20Lock%20--%20%22%EC%A0%90%EC%9C%A0%20%EC%8B%A4%ED%8C%A8%20(%EC%82%AC%EC%9A%A9%20%EC%A4%91)%22%20--%3E%20Retry%5B%22%EB%8C%80%EA%B8%B0%EC%97%B4%20%ED%9B%84%EC%88%9C%EC%9C%84%20%EC%9E%AC%EB%B0%B0%EC%B9%98%20%EB%B0%8F%20%EC%A7%80%EC%88%98%20%EB%B0%B1%EC%98%A4%ED%94%84%22%5D%0A%20%20%20%20Lock%20--%20%22%EC%A0%90%EC%9C%A0%20%EC%84%B1%EA%B3%B5%22%20--%3E%20Exec%5B%22%EB%8C%80%EC%83%81%20%EB%8B%A8%EB%A7%90%EA%B8%B0%20%EC%8B%9C%EB%82%98%EB%A6%AC%EC%98%A4%20%EB%B3%91%EB%A0%AC%20%EC%8B%A4%ED%96%89%22%5D%0A%20%20%20%20%0A%20%20%20%20subgraph%20RunProcess%20%5B%22%EC%8B%A4%ED%96%89%20%EB%B0%8F%20%ED%92%88%EC%A7%88%20%EA%B2%80%EC%A6%9D%20%ED%8C%8C%EC%9D%B4%ED%94%84%EB%9D%BC%EC%9D%B8%22%5D%0A%20%20%20%20%20%20%20%20Exec%20--%3E%20Replay%5B%22%EB%AC%B4%EC%9D%B8%20%EC%A0%9C%EC%8A%A4%EC%B2%98%20Replay%22%5D%0A%20%20%20%20%20%20%20%20Replay%20--%3E%20Mask%5B%22%EB%85%B8%EC%B9%98%20%2F%20%EC%83%81%ED%83%9C%EB%B0%94%20%EC%98%81%EC%97%AD%20%EC%9E%90%EB%8F%99%20%EB%A7%88%EC%8A%A4%ED%82%B9%22%5D%0A%20%20%20%20%20%20%20%20Mask%20--%3E%20Visual%5B%22Pixelmatch%20%EA%B8%B0%EB%B0%98%20%EC%8B%9C%EA%B0%81%EC%A0%81%20%ED%9A%8C%EA%B7%80%20%ED%8C%90%EC%A0%95%22%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20RunProcess%20--%3E%20Release%5B%22Heartbeat%20%EB%A7%8C%EB%A3%8C%20%EB%B0%8F%20%EB%B6%84%EC%82%B0%20%EB%9D%BD%20%EC%95%88%EC%A0%84%20%ED%95%B4%EC%A0%9C%22%5D%0A%20%20%20%20Release%20--%3E%20Report%5B%22%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EA%B2%B0%EA%B3%BC%20%ED%86%B5%EA%B3%84%20%EB%B0%8F%20%EC%8B%A4%ED%8C%A8%20%EC%8A%A4%EB%83%85%EC%83%B7%20%EB%A6%AC%ED%8F%AC%ED%8A%B8%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[C(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-redis-분산-락-기반-기기-점유-제어" tabindex="-1">2. Redis 분산 락 기반 기기 점유 제어 <a class="header-anchor" href="#_2-redis-분산-락-기반-기기-점유-제어" aria-label="Permalink to “2. Redis 분산 락 기반 기기 점유 제어”">​</a></h2><p>단말기 중복 제어를 방지하기 위해 Redis를 활용한 분산 락 메커니즘을 적용합니다.</p><ul><li><strong>락 획득 규격</strong>: <ul><li>키 포맷: <code>device:lock:{platform}:{deviceId}</code> (예: <code>device:lock:android:emulator-5554</code>)</li><li>원자적 연산: Redis <code>SET key value NX PX 120000</code> (기본 타임아웃 120초)</li></ul></li><li><strong>Heartbeat 갱신 및 안전 해제</strong>: <ul><li>테스트 러너 프로세스는 매 30초마다 락의 만료 시간(TTL)을 갱신합니다.</li><li>만약 네트워크 단절이나 프로세스 비정상 크래시가 발생하더라도, 120초 후 Redis 키가 자동으로 만료(Auto-Release)되어 단말기가 영구 잠김 상태에 빠지는 것을 방지합니다.</li></ul></li></ul><hr><h2 id="_3-노치-및-상태바-자동-마스킹-시각적-회귀-검증" tabindex="-1">3. 노치 및 상태바 자동 마스킹 시각적 회귀 검증 <a class="header-anchor" href="#_3-노치-및-상태바-자동-마스킹-시각적-회귀-검증" aria-label="Permalink to “3. 노치 및 상태바 자동 마스킹 시각적 회귀 검증”">​</a></h2><p>모바일 화면의 픽셀 단위 회귀 검증(Visual Regression Testing) 시 불필요한 오탐을 제거하기 위해 3단계 마스킹 파이프라인을 가동합니다.</p><ol><li><strong>상단 상태 표시줄(Status Bar) 정적 마스킹</strong>: <ul><li>기기별 OS 설정에서 수집된 상단 바 높이(예: Android 24dp, iOS 다이내믹 아일랜드 54pt) 영역을 비교 대상에서 제외(Zero-Alpha 처리)합니다.</li></ul></li><li><strong>하단 제스처 내비게이션 바(Home Bar) 마스킹</strong>: <ul><li>전체 화면 모드가 아닌 경우 하단 16~20dp 영역의 시스템 바를 마스킹합니다.</li></ul></li><li><strong>Pixelmatch 기반 유효 임계치 비교</strong>: <ul><li>마스킹된 영역을 제외한 본문 컨텐츠 영역에 대해 <code>pixelmatch</code> 라이브러리를 실행하여, 픽셀 차이율이 사전에 정의된 허용 임계치(예: 0.1% 이하) 이내인 경우 정상으로 판정합니다.</li></ul></li></ol><hr><h2 id="_4-야간-배치-파이프라인-운영-기준" tabindex="-1">4. 야간 배치 파이프라인 운영 기준 <a class="header-anchor" href="#_4-야간-배치-파이프라인-운영-기준" aria-label="Permalink to “4. 야간 배치 파이프라인 운영 기준”">​</a></h2><ul><li><strong>스케줄링 주기</strong>: 매일 새벽 02:00 ~ 05:00에 전사 등록 시나리오 전수 회귀 테스트 실행.</li><li><strong>실패 시 격리 보존</strong>: <ul><li>테스트 실패 감지 시 즉시 현재 화면 캡처, 직전 10초간의 로그캣(Logcat) 또는 시스템 콘솔 로그를 번들링하여 S3/MinIO에 영구 적재.</li><li>실패 지점의 화면과 기준(Baseline) 화면의 차이점을 오버레이한 Diff 이미지를 리포트에 자동 첨부하여 익일 아침 개발팀이 원인을 즉시 파악할 수 있도록 지원합니다.</li></ul></li></ul>',11))])}const g=B(n,[["render",d]]);export{m as __pageData,g as default};
